import{_ as t,c as a,o as r,ae as o}from"./chunks/framework.CliRSA9F.js";const g=JSON.parse('{"title":"Agency Workspace","description":"Manage an Agency portfolio, create client and prospect reports, and review episode and social content in PodSEO.","frontmatter":{"description":"Manage an Agency portfolio, create client and prospect reports, and review episode and social content in PodSEO."},"headers":[],"relativePath":"features/agency-workspace.md","filePath":"features/agency-workspace.md"}'),n={name:"features/agency-workspace.md"};function s(i,e,p,d,c,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="agency-workspace" tabindex="-1">Agency Workspace <a class="header-anchor" href="#agency-workspace" aria-label="Permalink to &quot;Agency Workspace&quot;">​</a></h1><p>The Agency workspace brings multiple client podcasts, reports, and approval requests together. It is available to organizations on the <strong>Agency plan</strong>. Switch to your organization account, then open <strong>Agency workspace</strong> in the sidebar. Team access depends on your role and podcast assignments; see <a href="/features/teams-and-organizations.html">Teams and Organizations</a>.</p><h2 id="review-your-portfolio-and-clients" tabindex="-1">Review your portfolio and clients <a class="header-anchor" href="#review-your-portfolio-and-clients" aria-label="Permalink to &quot;Review your portfolio and clients&quot;">​</a></h2><p>Start with the portfolio to choose which shows need attention, then open a client workspace for its evidence and activity. Use the Clients view to navigate client podcasts. Owners and admins manage the workspace; collaborators only see the information their access permits. Client viewers are restricted to assigned shows.</p><h2 id="create-a-client-report" tabindex="-1">Create a client report <a class="header-anchor" href="#create-a-client-report" aria-label="Permalink to &quot;Create a client report&quot;">​</a></h2><ol><li>Open <strong>Reports</strong> and create a new report.</li><li>Choose the podcast, reporting dates, and sections to include.</li><li>Generate the report, then add commentary explaining the changes and next steps.</li><li>Choose a reviewer if needed and mark the report <strong>Ready for review</strong>.</li><li>The assigned reviewer can approve it or request changes with a comment. Revise and resubmit when needed.</li></ol><p>Reports capture a snapshot for the selected period. They are not live dashboards, so a later ranking change does not silently rewrite a report you already shared. Configure your report branding in <strong>Brand &amp; settings</strong> before creating reports; existing reports retain their captured branding.</p><h2 id="brand-settings-monthly-reports-and-digest" tabindex="-1">Brand &amp; settings: monthly reports and digest <a class="header-anchor" href="#brand-settings-monthly-reports-and-digest" aria-label="Permalink to &quot;Brand &amp; settings: monthly reports and digest&quot;">​</a></h2><p>Besides your logo, accent color, footer text, contact email, and website, <strong>Brand &amp; settings</strong> has two options that save routine work:</p><ul><li><strong>Monthly reports</strong>: turn this on to have PodSEO create private monthly report drafts on the day of the month you choose (from 1 to 28). Drafts are never shared or sent automatically. Review each one, add commentary, and share it yourself when it&#39;s ready.</li><li><strong>Digest</strong>: turn this on to receive the workspace&#39;s attention queue (the shows and items that need your attention) through your existing <a href="/features/notifications.html">notification preferences</a>.</li></ul><h2 id="share-print-and-record-delivery" tabindex="-1">Share, print, and record delivery <a class="header-anchor" href="#share-print-and-record-delivery" aria-label="Permalink to &quot;Share, print, and record delivery&quot;">​</a></h2><p>Use <strong>Enable share link</strong> when the report is ready to share. Anyone with that link can open the public report, so check its contents and recipient before sending it. Links expire after 90 days; <strong>Revoke link</strong> disables the old link. Returning a report to draft also withdraws its existing share link.</p><p>The print view is suitable for printing or saving as PDF with your browser. After sending an approved report yourself, record its recipient and mark it as sent. <strong>Marking it sent records delivery; it does not send an email.</strong> Workspace exports provide downloadable data for your own reporting.</p><h2 id="research-prospects" tabindex="-1">Research prospects <a class="header-anchor" href="#research-prospects" aria-label="Permalink to &quot;Research prospects&quot;">​</a></h2><p>Owners and admins can use <strong>Prospects</strong> to search the catalog and create a prospect audit. Use this to prepare a discovery conversation before bringing a show into your client portfolio. An audit describes the available evidence; it does not grant ownership of the show or change its metadata.</p><h2 id="request-episode-and-social-post-approvals" tabindex="-1">Request episode and social-post approvals <a class="header-anchor" href="#request-episode-and-social-post-approvals" aria-label="Permalink to &quot;Request episode and social-post approvals&quot;">​</a></h2><p>An owner or admin first assigns a client reviewer to the podcast, then uses the client workspace&#39;s review action to submit a planned episode or social post. Return a scheduled social post to draft before requesting approval; already published episodes cannot be submitted. They open <strong>Approvals</strong>, review the submitted version, and approve it or request changes with a comment.</p><p>Approval applies to that version. If the content changes, submit the updated version for review; an earlier approval does not cover new content. Where a review is required, publishing or marking an episode published must satisfy that review. Approving a planned episode does not upload audio to a podcast host.</p><p>If a reviewer loses access, an owner or admin needs to reassign the review or clear the requirement — removing a teammate doesn&#39;t approve their outstanding work.</p><p>For a practical routine, review the portfolio weekly, use <a href="/features/planner.html">Planner</a> for upcoming episodes, and create a report with commentary at the end of each client reporting period.</p>',20)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
